sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    var prevRecord=api.data.look_up_multiple_records_1.results[0];
    var curRecord=api.data.decision_side_panel.form.fields;
    for (var key in prevRecord) {
    if (curRecord.hasOwnProperty(key)) { 
        console.log(prevRecord[key])
        curRecord[key].value=prevRecord[key].value;
        curRecord[key].displayValue=prevRecord[key].displayValue;
        curRecord[key]=prevRecord[key]
    }
}
    console.log(api.data.look_up_multiple_records_1.results)
}
